export const getGetTournamentRoomUrl = (id: string,
    params: GetTournamentRoomParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/tournaments/${id}/room?${stringifiedParams}` : `/api/tournaments/${id}/room`
}

